// Copyright (c) 2026 VEOR Browser Authors. All rights reserved.  #include “update/UpdateChecker.h”  #include “base/json/json_reader.h” #include “base/strings/string_number_conversions.h” #include “base/strings/string_util.h” #include “base/task/single_thread_task_runner.h” #include “base/time/time.h” #include “core/logging/VeorLogger.h” #include “net/traffic_annotation/network_traffic_annotation.h”  namespace veor {  namespace {  constexpr char kVersionEndpoint[] = “https://veor.dev/api/version”; constexpr char kCurrentVersion[] = “0.1.0-alpha”; // TODO: Generate from build  constexpr base::TimeDelta kCheckInterval = base::Hours(24);  } // namespace  UpdateChecker::UpdateChecker() = default; UpdateChecker::~UpdateChecker() = default;  std::string UpdateChecker::GetCurrentVersion() {   return kCurrentVersion; }  void UpdateChecker::CheckForUpdate(     base::OnceCallback<void(bool update_available,                             const std::string& version)> on_result) {   VEOR_LOGI(LogCategory::kInfrastructure, “Checking for updates…”);   pending_callback_ = std::move(on_result);    // TODO: Implement actual HTTP fetch via NetworkService   // For now, simulate no update available after a short delay   base::SingleThreadTaskRunner::GetCurrentDefault()->PostDelayedTask(       FROM_HERE,       base::BindOnce(&UpdateChecker::OnCheckComplete,                      weak_factory_.GetWeakPtr(),                      std::string()),       base::Seconds(2)); }  void UpdateChecker::OnCheckComplete(const std::string& response_body) {   if (response_body.empty()) {     // No response — assume no update or offline     if (pending_callback_)       std::move(pending_callback_).Run(false, std::string());     return;   }    auto parsed = base::JSONReader::Read(response_body);   if (!parsed || !parsed->is_dict()) {     VEOR_LOGW(LogCategory::kInfrastructure, “Invalid version response”);     if (pending_callback_)       std::move(pending_callback_).Run(false, std::string());     return;   }    const auto& dict = parsed->GetDict();   const std::string* latest = dict.FindString(“latest_version”);   if (!latest) {     if (pending_callback_)       std::move(pending_callback_).Run(false, std::string());     return;   }    std::string current = GetCurrentVersion();   bool update_available = (*latest != current);    if (update_available) {     VEOR_LOGI(LogCategory::kInfrastructure,                “Update available: ” + *latest + “ (current: ” + current + “)”);   } else {     VEOR_LOGI(LogCategory::kInfrastructure, “Browser is up to date”);   }    if (pending_callback_)     std::move(pending_callback_).Run(update_available, *latest); }  void UpdateChecker::StartPeriodicChecks() {   if (periodic_checks_active_)     return;   periodic_checks_active_ = true;   ScheduleNextCheck(); }  void UpdateChecker::StopPeriodicChecks() {   periodic_checks_active_ = false; }  void UpdateChecker::ScheduleNextCheck() {   if (!periodic_checks_active_)     return;    base::SingleThreadTaskRunner::GetCurrentDefault()->PostDelayedTask(       FROM_HERE,       base::BindOnce(&UpdateChecker::CheckForUpdate,                      weak_factory_.GetWeakPtr(),                      base::BindOnce([](bool available, const std::string& version) {                        // Silently log periodic check results                        // Toast only shown on explicit user check or if update found                        if (available) {                          VEOR_LOGI(LogCategory::kInfrastructure,                                     “Periodic check: update available ” + version);                        }                      })),       kCheckInterval); }  } // namespace veor